const reqs = $('Build Probe Requests').all();
const res = $input.all();
const out = [];
for (let i = 0; i < res.length; i++) {
  const meta = (reqs[i] || { json: {} }).json;
  const r = res[i].json || {};
  const hdr = r.headers || {};
  const body = r.body || {};
  const rec = {
    label: meta.label,
    status: r.statusCode,
    total: hdr['x-pagination-total-count'],
    body_top_keys: Object.keys(body).join(','),
    error: body.error ? JSON.stringify(body.error) : null
  };
  const keys = body.keys || [];
  if (keys.length > 0) {
    rec.key_fields = Object.keys(keys[0]).join(',');
    rec.first_key_name = JSON.stringify(keys[0].key_name || null);
    const trs = keys[0].translations || [];
    rec.translation_count = trs.length;
    if (trs.length > 0) {
      rec.translation_fields = Object.keys(trs[0]).join(',');
      rec.sample_translation = JSON.stringify(trs[0]).slice(0, 900);
    }
  }
  const langs = body.languages || [];
  if (langs.length > 0) {
    rec.lang_fields = Object.keys(langs[0]).join(',');
    const compact = [];
    for (const L of langs) { compact.push(L.lang_iso + '=' + L.lang_id); }
    rec.langs = compact.join(' ');
  }
  out.push({ json: rec });
}
return out;
